  TastePreference?: TastePreferenceResolvers<ContextType>;
  TasteDNAProfile?: TasteDnaProfileResolvers<ContextType>;
  RatingBucket?: RatingBucketResolvers<ContextType>;
  BingeStats?: BingeStatsResolvers<ContextType>;
  BingeRecommendationSection?: BingeRecommendationSectionResolvers<ContextType>;
  Genre?: GenreResolvers<ContextType>;
  CastMember?: CastMemberResolvers<ContextType>;
